Revise the ConcIR candidate for the same requirements. The requirements and the frozen contract are authoritative; the feedback is repair context.

<domain_requirements>
Design two workers A and B that each take two mutexes with an intermediate semaphore handshake, plus an independent bystander task that keeps making progress forever. Main spawns all three. Although the bystander keeps the system globally live, every reachable state must still be able to finish A and B, and both workers must complete.
</domain_requirements>

<contract>
{
  "name": "partial-bystander",
  "properties": [
    {
      "kind": "deadlock_free",
      "id": "no-deadlock"
    },
    {
      "kind": "always_reachable",
      "id": "a-completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::a"
      }
    },
    {
      "kind": "always_reachable",
      "id": "b-completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::b"
      }
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::a completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::a"
      }
    },
    {
      "kind": "reachable",
      "description": "main::b completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::b"
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

